const std = @import("std");

fn strassen2(A: [2][2]i32, B: [2][2]i32) [2][2]i32 {
    const a = A[0][0]; const b = A[0][1]; const c = A[1][0]; const d = A[1][1];
    const e = B[0][0]; const f = B[0][1]; const g = B[1][0]; const h = B[1][1];

    const p1 = a * (f - h);
    const p2 = (a + b) * h;
    const p3 = (c + d) * e;
    const p4 = d * (g - e);
    const p5 = (a + d) * (e + h);
    const p6 = (b - d) * (g + h);
    const p7 = (a - c) * (e + f);

    return [2][2]i32{
        [_]i32{ p5 + p4 - p2 + p6, p1 + p2 },
        [_]i32{ p3 + p4, p1 + p5 - p3 - p7 },
    };
}

pub fn main() !void {
    const A = [2][2]i32{ [_]i32{ 1, 2 }, [_]i32{ 3, 4 } };
    const B = [2][2]i32{ [_]i32{ 5, 6 }, [_]i32{ 7, 8 } };
    const C = strassen2(A, B);

    for (C) |row| {
        for (row) |val| std.debug.print("{} ", .{val});
        std.debug.print("\n", .{});
    }
}
